if __name__ == "__main__":
    out = Path(__file__).parent
    for i, (title, topic, part1, part2) in enumerate(STORIES, start=1):
        data = {
            "title": title,
            "topic": topic,
            "text": f"{part1.strip()}\n[CORTE]\n{part2.strip()}",
        }
        path = out / f"{i:02d}_historia.json"
        path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
        words = [len(p.split()) for p in (part1, part2)]
        print(f"{path.name}: {title} ({words[0]} + {words[1]} palabras)")
